mapper.select:
SELECT lnk.DICT_CODE DICT_CODE, lnk.ITEM_CODE ITEM_CODE, lst1.ITEM_VALUE ITEM_VALUE, lnk.LINKED_DICT_CODE LINKED_DICT_CODE, lnk.LINKED_ITEM_CODE LINKED_ITEM_CODE, lst2.ITEM_VALUE LINKED_ITEM_VALUE FROM SYS_DATADICT_LIST_LINK lnk left join SYS_DATADICT_LIST lst1 on lst1.DICT_CODE = lnk.DICT_CODE and lst1.ITEM_CODE = lnk.ITEM_CODE left join SYS_DATADICT_LIST lst2 on lst2.DICT_CODE = lnk.LINKED_DICT_CODE and lst2.ITEM_CODE = lnk.LINKED_ITEM_CODE WHERE 1=1
and lnk.DICT_CODE = #{dctCode, jdbcType=VARCHAR}
and lnk.ITEM_CODE = #{itmCode, jdbcType=VARCHAR}
and lnk.LINKED_DICT_CODE = #{lnkDict, jdbcType=VARCHAR}
and lnk.LINKED_ITEM_CODE = #{lnkItem, jdbcType=VARCHAR}
and lst1.ITEM_VALUE = #{itemVal, jdbcType=VARCHAR}
and lst2.ITEM_VALUE = #{lnkdVal, jdbcType=VARCHAR}
